import java.util.*;
import java.util.concurrent.*;
import java.math.*;

/*
 * Provided Html Parser implementation. You should NOT modify it.
 */
class HtmlParser {
    private final Map<String, List<String>> graph;

    HtmlParser(String[] urls, int[][] edges) {
        graph = new ConcurrentHashMap<>();
        for (String u : urls) {
            graph.put(u, new ArrayList<>());
        }
        for (int[] edge : edges) {
            int from = edge[0];
            int to = edge[1];
            graph.get(urls[from]).add(urls[to]);
        }
    }

    public List<String> getUrls(String url) {
        try {
            Thread.sleep(10); // Simulate network latency
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        List<String> links = graph.get(url);
        if (links == null) {
            return Collections.emptyList();
        }
        return links;
    }
}

public class Solution {
    public List<String> crawl(String startUrl, HtmlParser htmlParser) {
        String startHost = getHost(startUrl);
        Set<String> visited = ConcurrentHashMap.newKeySet();
        ExecutorService pool = Executors.newFixedThreadPool(Math.max(4, Runtime.getRuntime().availableProcessors()));
        Phaser phaser = new Phaser(1); // main thread registered

        String sanitizedStart = sanitize(startUrl);
        visited.add(sanitizedStart);
        submitTask(startUrl, htmlParser, startHost, visited, pool, phaser);

        // Wait for all crawl tasks to complete
        phaser.arriveAndAwaitAdvance();
        pool.shutdown();

        List<String> result = new ArrayList<>(visited);
        return result;
    }

    private void submitTask(String url, HtmlParser parser, String host, Set<String> visited, ExecutorService pool,
            Phaser phaser) {
        phaser.register();
        pool.submit(() -> {
            try {
                List<String> urls = parser.getUrls(url);
                for (String next : urls) {
                    String sanitized = sanitize(next);
                    String nextHost = getHost(sanitized);
                    if (!nextHost.equals(host)) {
                        continue;
                    }
                    // only schedule if not already visited
                    if (visited.add(sanitized)) {
                        submitTask(next, parser, host, visited, pool, phaser);
                    }
                }
            } finally {
                phaser.arriveAndDeregister();
            }
        });
    }

    private String getHost(String url) {
        // Remove scheme (http:// or https://)
        int start = url.indexOf("://");
        if (start == -1) {
            start = 0;
        } else {
            start = start + 3;
        }

        int end = url.indexOf('/', start);
        if (end == -1) {
            end = url.length();
        }

        return url.substring(start, end);
    }

    private String sanitize(String url) {
        int idx = url.indexOf('#');
        if (idx == -1) {
            return url;
        }

        return url.substring(0, idx);
    }

    public static void main(String[] args) {
        test1();
        test2();
        test3();
    }

    private static void test1() {
