        if (links == null) {
            return [];
        }
        return links;
    }
}

class Solution {
    public async crawl(startUrl: string, htmlParser: HtmlParser): Promise<string[]> {
        const startHost = this.getHost(startUrl);
        const visited = new Set<string>();
        let activeTasks = 0;
        const taskPromises: Promise<void>[] = [];

        const sanitizedStart = this.sanitize(startUrl);
        visited.add(sanitizedStart);
        
        const submitTask = async (url: string): Promise<void> => {
            activeTasks++;
            try {
                const urls = await htmlParser.getUrls(url);
                const newTasks: Promise<void>[] = [];
                
                for (const next of urls) {
                    const sanitized = this.sanitize(next);
                    const nextHost = this.getHost(sanitized);
                    if (nextHost !== startHost) {
                        continue;
                    }
                    // only schedule if not already visited
                    if (!visited.has(sanitized)) {
                        visited.add(sanitized);
                        newTasks.push(submitTask(next));
                    }
                }
                
                await Promise.all(newTasks);
            } finally {
                activeTasks--;
            }
        };

        await submitTask(startUrl);

        const result = Array.from(visited);
