using namespace std;

/*
 * Provided HtmlParser implementation. You should NOT modify it.
 */
class HtmlParser {
private:
    unordered_map<string, vector<string>> graph;

public:
    HtmlParser(const vector<string>& urls, const vector<vector<int>>& edges) {
        for (const string& u : urls) {
            graph[u] = vector<string>();
        }
        for (const auto& edge : edges) {
            int from = edge[0];
            int to = edge[1];
            auto itFrom = graph.find(urls[from]);
            if (itFrom != graph.end()) {
                itFrom->second.push_back(urls[to]);
            }
        }
    }

    vector<string> getUrls(const string& url) {
        // Simulate network latency
        this_thread::sleep_for(chrono::milliseconds(10));

        auto it = graph.find(url);
        if (it == graph.end()) {
            return {};
        }
        return it->second;
    }
};

class Solution {
public:
    vector<string> crawl(const string& startUrl, HtmlParser& htmlParser) {
        string startHost = getHost(startUrl);
        string sanitizedStart = sanitize(startUrl);

        unordered_set<string> visited;
        mutex visitedMutex;

        atomic<int> activeTasks(0);
        mutex cvMutex;
        condition_variable cv;

        // Recursive task submission using lambda capture
        function<void(const string&)> submitTask = [&](const string& url) {
            activeTasks.fetch_add(1, memory_order_relaxed);
            thread([&, url]() {
                try {
                    vector<string> urls = htmlParser.getUrls(url);
                    for (const string& next : urls) {
                        string sanitized = sanitize(next);
                        string nextHost = getHost(sanitized);

                        if (nextHost != startHost) {
                            continue;
                        }

                        bool shouldSchedule = false;
                        {
                            lock_guard<mutex> lock(visitedMutex);
                            auto res = visited.insert(sanitized);
                            if (res.second) { // newly inserted
                                shouldSchedule = true;
                            }
                        }

                        if (shouldSchedule) {
                            submitTask(next);
                        }
                    }
                } catch (...) {
                    // Ignore any exceptions in worker threads
                }

                int remaining = activeTasks.fetch_sub(1, memory_order_acq_rel) - 1;
                if (remaining == 0) {
                    unique_lock<mutex> lock(cvMutex);
                    cv.notify_one();
                }
            }).detach();
        };

        {
            lock_guard<mutex> lock(visitedMutex);
            visited.insert(sanitizedStart);
        }

        // Start the first task
        submitTask(startUrl);

        // Wait until all tasks are finished
        {
            unique_lock<mutex> lock(cvMutex);
            cv.wait(lock, [&]() { return activeTasks.load(memory_order_acquire) == 0; });
        }

        vector<string> result;
        {
            lock_guard<mutex> lock(visitedMutex);
            result.assign(visited.begin(), visited.end());
        }
        return result;
    }

private:
    string getHost(const string& url) {
        // Remove scheme (http:// or https://)
        size_t start = url.find("://");
        if (start == string::npos) {
            start = 0;
        } else {
            start = start + 3;
        }

        size_t end = url.find('/', start);
        if (end == string::npos) {
            end = url.size();
        }

        return url.substr(start, end - start);
    }

    string sanitize(const string& url) {
        size_t idx = url.find('#');
        if (idx == string::npos) {
            return url;
        }
        return url.substr(0, idx);
    }
};

