import java.util.*;
import java.math.*;

class Trie {
    Map<Character, Trie> children;
    String id;

    Trie() {
        children = new HashMap<>();
        id = null;
    }
}

class Solution {
    public List<String> tokenize(String text, List<String> dictionary) {
        Trie root = buildTrie(dictionary);
        List<String> result = new ArrayList<>();

        int i = 0;
        while (i < text.length()) {
            // Try to find longest match starting at position i
            Trie node = root;
            String bestId = null;
            int bestEnd = i;

            int j = i;
            while (j < text.length()) {
                char c = text.charAt(j);
                if (!node.children.containsKey(c)) {
                    break;
                }
                node = node.children.get(c);
                j = j + 1;

                // Track the last terminal node we've seen
                if (node.id != null) {
                    bestId = node.id;
                    bestEnd = j;
                }
            }

            if (bestId != null) {
                result.add(bestId);
                i = bestEnd;
            } else {
                // No match found, emit literal character
                result.add(String.valueOf(text.charAt(i)));
                i = i + 1;
            }
        }

        return result;
    }

    private Trie buildTrie(List<String> dictionary) {
        Trie root = new Trie();

        for (String entry : dictionary) {
            int colonIndex = entry.indexOf(':');
            if (colonIndex == -1) {
                continue;
            }

            String key = entry.substring(0, colonIndex);
            String val = entry.substring(colonIndex + 1);

            Trie node = root;
            for (int i = 0; i < key.length(); i++) {
                char c = key.charAt(i);
                if (!node.children.containsKey(c)) {
                    node.children.put(c, new Trie());
                }
                node = node.children.get(c);
            }
            // Last wins if duplicate keys
            node.id = val;
        }

        return root;
    }
}

