class Trie {
public:
    unordered_map<char, Trie*> children;
    string id;

    Trie() {
        id = "";
    }
};

class Solution {
public:
    vector<string> tokenize(string text, vector<string> dictionary) {
        Trie* root = buildTrie(dictionary);
        vector<string> result;

        int i = 0;
        while (i < text.length()) {
            // Try to find longest match starting at position i
            Trie* node = root;
            string bestId = "";
            int bestEnd = i;

            int j = i;
            while (j < text.length()) {
                char c = text[j];
                if (node->children.find(c) == node->children.end()) {
                    break;
                }
                node = node->children[c];
                j = j + 1;

                // Track the last terminal node we've seen
                if (!node->id.empty()) {
                    bestId = node->id;
                    bestEnd = j;
                }
            }

            if (!bestId.empty()) {
                result.push_back(bestId);
                i = bestEnd;
            } else {
                // No match found, emit literal character
                result.push_back(string(1, text[i]));
                i = i + 1;
            }
        }

        return result;
    }

private:
    Trie* buildTrie(vector<string> dictionary) {
        Trie* root = new Trie();

        for (string entry : dictionary) {
            int colonIndex = entry.find(':');
            if (colonIndex == string::npos) {
                continue;
            }

            string key = entry.substr(0, colonIndex);
            string val = entry.substr(colonIndex + 1);

            Trie* node = root;
            for (int i = 0; i < key.length(); i++) {
                char c = key[i];
                if (node->children.find(c) == node->children.end()) {
                    node->children[c] = new Trie();
                }
                node = node->children[c];
            }
            // Last wins if duplicate keys
            node->id = val;
        }

        return root;
    }
};
